using System.Text.Json;
namespace ToneCustoms.ShellStudio.Props;
public sealed record PropAsset(string Name,string Model,string Category,string? SourcePath=null,string[]? Tags=null,bool IsGta=true);
public sealed class PropCatalog { readonly List<PropAsset> _items=[]; public IReadOnlyList<PropAsset> Items=>_items; static readonly HashSet<string> ImportExt=new(StringComparer.OrdinalIgnoreCase){".glb",".gltf",".fbx",".obj",".ydr"}; public PropAsset AddCustom(string path,string category="Custom"){if(!File.Exists(path))throw new FileNotFoundException("Prop model not found.",path);if(!ImportExt.Contains(Path.GetExtension(path)))throw new NotSupportedException("Supported prop formats: GLB, GLTF, FBX, OBJ, YDR.");var p=new PropAsset(Path.GetFileNameWithoutExtension(path),Path.GetFileNameWithoutExtension(path),category,path,["custom","imported"],false);_items.Add(p);return p;} public void AddGta(string model,string category="GTA V",params string[] tags){if(string.IsNullOrWhiteSpace(model))return;if(_items.Any(x=>x.Model.Equals(model,StringComparison.OrdinalIgnoreCase)))return;_items.Add(new(model,model,category,null,tags,true));} public IEnumerable<PropAsset> Search(string? q,string? category=null){IEnumerable<PropAsset> r=_items;if(!string.IsNullOrWhiteSpace(category)&&category!="All")r=r.Where(x=>x.Category.Equals(category,StringComparison.OrdinalIgnoreCase));if(!string.IsNullOrWhiteSpace(q))r=r.Where(x=>x.Name.Contains(q,StringComparison.OrdinalIgnoreCase)||x.Model.Contains(q,StringComparison.OrdinalIgnoreCase)||x.Category.Contains(q,StringComparison.OrdinalIgnoreCase)||(x.Tags?.Any(t=>t.Contains(q,StringComparison.OrdinalIgnoreCase))??false));return r.OrderBy(x=>x.Category).ThenBy(x=>x.Name);} public async Task LoadIndexAsync(string json,CancellationToken ct=default){if(!File.Exists(json))return;var items=JsonSerializer.Deserialize<List<PropAsset>>(await File.ReadAllTextAsync(json,ct))??[];foreach(var p in items)if(!_items.Any(x=>x.Model.Equals(p.Model,StringComparison.OrdinalIgnoreCase)))_items.Add(p);} }
